function dispatchOrder(turn) {
  if (!turn || typeof turn !== 'object' || turn.tool !== 'sumItems') {
    return { ok: false, error: 'unknown-tool' };
  }
  const count = turn.args?.count;
  const extra = turn.args?.extra;
  const valid = Number.isInteger(count) && count >= 0 && count <= 100 &&
    Number.isInteger(extra) && extra >= 0 && extra <= 100;
  if (!valid) return { ok: false, error: 'invalid-args' };
  return { ok: true, value: count + extra };
}

