function estimateCharge(usage) {
  const { input, cached, output } = usage ?? {};
  const valid = [input, cached, output].every(
    (count) => Number.isInteger(count) && count >= 0 && count <= 1000000
  );
  if (!valid || cached > input) return null;
  return (input - cached) * 2 + cached + output * 5;
}

