Ожидаемый вывод: F1:queue | F2:review | F3:invalid-review | F4:review.
Модель может предложить вердикт из вымышленного сообщения. Код валидирует поля и направляет refund к человеку даже при false. Человек рассматривает возврат и решает отдельно, закрывать ли заявку.

function routeVerdicts(items) {
  return items.map(({ id, verdict }) => {
    const valid = verdict && typeof verdict === 'object' && !Array.isArray(verdict) &&
      ['technical', 'refund', 'general'].includes(verdict.category) &&
      ['low', 'high'].includes(verdict.priority) && typeof verdict.needsHuman === 'boolean';
    if (!valid) return { id, route: 'invalid-review' };
    if (verdict.category === 'refund') return { id, route: 'review' };
    if (verdict.needsHuman) return { id, route: 'review' };
    return { id, route: 'queue' };
  });
}

const records = [
  { id: 'F1', verdict: { category: 'general', priority: 'low', needsHuman: false } },
  { id: 'F2', verdict: { category: 'refund', priority: 'high', needsHuman: false } },
  { id: 'F3', verdict: { category: 'technical', needsHuman: false } },
  { id: 'F4', verdict: { category: 'technical', priority: 'high', needsHuman: true } },
];
console.log(routeVerdicts(records).map(({ id, route }) => `${id}:${route}`).join(' | '));

